import { Block } from '../block';
import type { MathOp } from '../field/math-op';
import type { Input } from '../input';

/**
 * Typed factories for Scratch "Operators" blocks.
 *
 * Generated by bin/generate-blocks.ts — do not edit by hand.
 */
export const Operators = {
  add(num1: number | Block | Input, num2: number | Block | Input): Block {
    return Block.make('operator_add')
      .input('NUM1', num1)
      .input('NUM2', num2);
  },

  subtract(num1: number | Block | Input, num2: number | Block | Input): Block {
    return Block.make('operator_subtract')
      .input('NUM1', num1)
      .input('NUM2', num2);
  },

  multiply(num1: number | Block | Input, num2: number | Block | Input): Block {
    return Block.make('operator_multiply')
      .input('NUM1', num1)
      .input('NUM2', num2);
  },

  divide(num1: number | Block | Input, num2: number | Block | Input): Block {
    return Block.make('operator_divide')
      .input('NUM1', num1)
      .input('NUM2', num2);
  },

  random(from: number | Block | Input, to: number | Block | Input): Block {
    return Block.make('operator_random')
      .input('FROM', from)
      .input('TO', to);
  },

  lt(operand1: number | string | Block | Input, operand2: number | string | Block | Input): Block {
    return Block.make('operator_lt')
      .input('OPERAND1', operand1)
      .input('OPERAND2', operand2);
  },

  equals(operand1: number | string | Block | Input, operand2: number | string | Block | Input): Block {
    return Block.make('operator_equals')
      .input('OPERAND1', operand1)
      .input('OPERAND2', operand2);
  },

  gt(operand1: number | string | Block | Input, operand2: number | string | Block | Input): Block {
    return Block.make('operator_gt')
      .input('OPERAND1', operand1)
      .input('OPERAND2', operand2);
  },

  and(operand1: Block, operand2: Block): Block {
    return Block.make('operator_and')
      .input('OPERAND1', operand1)
      .input('OPERAND2', operand2);
  },

  or(operand1: Block, operand2: Block): Block {
    return Block.make('operator_or')
      .input('OPERAND1', operand1)
      .input('OPERAND2', operand2);
  },

  not(operand: Block): Block {
    return Block.make('operator_not')
      .input('OPERAND', operand);
  },

  join(string1: string | Block | Input, string2: string | Block | Input): Block {
    return Block.make('operator_join')
      .input('STRING1', string1)
      .input('STRING2', string2);
  },

  letterOf(letter: number | Block | Input, string: string | Block | Input): Block {
    return Block.make('operator_letter_of')
      .input('LETTER', letter)
      .input('STRING', string);
  },

  length(string: string | Block | Input): Block {
    return Block.make('operator_length')
      .input('STRING', string);
  },

  contains(string1: string | Block | Input, string2: string | Block | Input): Block {
    return Block.make('operator_contains')
      .input('STRING1', string1)
      .input('STRING2', string2);
  },

  mod(num1: number | Block | Input, num2: number | Block | Input): Block {
    return Block.make('operator_mod')
      .input('NUM1', num1)
      .input('NUM2', num2);
  },

  round(num: number | Block | Input): Block {
    return Block.make('operator_round')
      .input('NUM', num);
  },

  mathOp(num: number | Block | Input, operator: MathOp): Block {
    return Block.make('operator_mathop')
      .input('NUM', num)
      .field('OPERATOR', operator);
  }
};
